def patch(n,pm={},replaceprims={},headspecs={},extra='',drop=(),reason=None,keyshape=None):
 r=next(r for r in records if r['number']==n);d=create(r['icon_id']).draw()
 if drop:d=replace(d,primitives=tuple(p for p in d.primitives if p.element_id not in drop),contours=tuple(c for c in d.contours if not any(m in drop for m in c.members)),relationships=tuple(z for z in d.relationships if not any(m in drop for m in z.members)))
 save(n,emit(d,headspecs,replaceprims,pm)+'\n'+extra,reason or r['reason'],keyshape)

